CREATE OR REPLACE FUNCTION public.validate_locker_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.charge_mode NOT IN('Free','Daily','Monthly','One-time') OR NEW.rate<0 OR NEW.deposit<0 OR NEW.checkout_policy<>'Manual clearance' THEN RAISE EXCEPTION 'Invalid locker charges or clearance policy'; END IF; RETURN NEW;END $$;
CREATE TRIGGER locker_config_validate BEFORE INSERT OR UPDATE ON public.locker_configuration FOR EACH ROW EXECUTE FUNCTION public.validate_locker_configuration();
CREATE OR REPLACE FUNCTION public.require_locker_clearance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
-- Room transfers are continued accommodation, not permanent departure.
IF COALESCE(NEW.clearance_notes,'') NOT LIKE 'Room transfer:%' AND COALESCE(NEW.clearance_notes,'')<>'Room change on return' AND EXISTS(SELECT 1 FROM public.locker_allocations a JOIN public.lockers l ON l.id=a.locker_id WHERE a.employee_id=NEW.employee_id AND a.released_on IS NULL AND l.camp_id=NEW.camp_id) THEN RAISE EXCEPTION 'Release allocated lockers in Locker Management before permanent checkout. Temporary checkout keeps lockers allocated.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER locker_checkout_clearance BEFORE INSERT ON public.check_outs FOR EACH ROW EXECUTE FUNCTION public.require_locker_clearance();
CREATE OR REPLACE FUNCTION public.validate_locker_allocation_dates() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.allocated_on>CURRENT_DATE OR NEW.charge_mode NOT IN('Free','Daily','Monthly','One-time') OR NEW.charge_rate<0 OR NEW.deposit<0 OR (NEW.released_on IS NOT NULL AND (NEW.released_on<NEW.allocated_on OR NEW.released_on>CURRENT_DATE OR NEW.release_condition IS NULL OR NEW.key_returned IS NULL)) THEN RAISE EXCEPTION 'Invalid allocation, release or charge values'; END IF;RETURN NEW;END $$;
CREATE TRIGGER locker_allocation_validate BEFORE INSERT OR UPDATE ON public.locker_allocations FOR EACH ROW EXECUTE FUNCTION public.validate_locker_allocation_dates();
CREATE OR REPLACE FUNCTION public.audit_locker_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.locker_events(locker_id,kind,actor,previous_value,new_value,remarks) SELECT id,'Charge Configuration',auth.uid(),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW),'Applies to subsequent allocations' FROM public.lockers WHERE camp_id=NEW.camp_id;RETURN NEW;END $$;
CREATE TRIGGER locker_config_audit AFTER INSERT OR UPDATE ON public.locker_configuration FOR EACH ROW EXECUTE FUNCTION public.audit_locker_configuration();